∀ {B : Type u₁} [inst : CategoryTheory.Bicategory B] {C : Type u₂} [inst_1 : CategoryTheory.Bicategory C] {D : Type u₃}
  [inst_2 : CategoryTheory.Bicategory D] (F : CategoryTheory.StrictlyUnitaryPseudofunctor B C)
  (G : CategoryTheory.StrictlyUnitaryPseudofunctor C D) (X : B), (F.comp G).obj X = G.obj (F.obj X)

∀ (C : Type u) [inst : CategoryTheory.Category.{v, u} C] {X Y Z : CategoryTheory.Functor SimplexCategoryᵒᵖ C}
  (α : CategoryTheory.NatTrans X Y) (β : CategoryTheory.NatTrans Y Z) (X_1 : SimplexCategoryᵒᵖ),
  (CategoryTheory.CategoryStruct.comp α β).app X_1 = CategoryTheory.CategoryStruct.comp (α.app X_1) (β.app X_1)

∀ {C : Type u_1} {D : Type u_2} {inst : CategoryTheory.Category.{v_1, u_1} C}
  {inst_1 : CategoryTheory.Category.{v_2, u_2} D} {L : CategoryTheory.Functor C D}
  {W : CategoryTheory.MorphismProperty C} [self : L.IsLocalization W], W.IsInvertedBy L

∀ {C : Type u_1} {D : Type u_2} {inst : CategoryTheory.Category.{v_1, u_1} C}
  {inst_1 : CategoryTheory.Category.{v_2, u_2} D} {L : CategoryTheory.Functor C D}
  {W : CategoryTheory.MorphismProperty C} [self : L.IsLocalization W],
  (CategoryTheory.Localization.Construction.lift L ⋯).IsEquivalence

∀ {C : Type uC} [inst : CategoryTheory.Category.{uC', uC} C] {W : CategoryTheory.MorphismProperty C} {X Y : C}
  (w w_1 : X ⟶ Y) (e_w : w = w_1) (hw : W w),
  CategoryTheory.Localization.Construction.wIso w hw = CategoryTheory.Localization.Construction.wIso w_1 ⋯

